DELETE FROM experiences WHERE id NOT IN ('ariveguru', 'konversi', 'lovepack', 'physicswallah', 'renovateai');
INSERT OR REPLACE INTO experiences (id, name, role, work_start, work_end, location, description, type, works, gradient) VALUES
  ('ariveguru', 'AriveGuru Technology Solutions Pvt. Ltd.', 'Frontend Engineer', '2024-03-14', '2024-07-23', 'Bangalore', 'First engineering job, and the senior whose work I picked up left a few weeks in, so the client app and its roadmap became mine as a fresher. It was JavaScript with no types and real users already on it, which is a quick way to learn what a codebase costs you when nothing states the shape of your own data. Built health tracking and assessment apps for medical clients. Built RHIA, a voice-first assistant covering registration, appointments and front-desk tasks, and a JSON-to-React-Native converter so server-described components stopped being hand-written twice. Guided a junior engineer through an automated email and PDF pipeline — mostly getting HTML to render reliably in email, which is where that kind of project actually stalls. Engineers with five years on me started bringing their frontend problems to me while I was still the newest person in the room, and I could usually work them out on the spot. Asked more than once to think through UI and UX myself rather than build to a handed-down design, and those went into the product as proposed. I left knowing frontend was the part I was genuinely good at, and knowing why.', 'FULL_TIME', '["bvmrf","rhia"]', '{"from":"green","to":"teal"}');
INSERT OR REPLACE INTO experiences (id, name, role, work_start, work_end, location, description, type, works, gradient) VALUES
  ('konversi', 'Konversi Pvt. Ltd.', 'Mobile Developer', '2024-10-01', '2025-04-30', 'Remote', 'Sole developer on three apps: vehicle maintenance for a trucking operation, point of sale for a park, and verified attendance. Each was mine end to end — architecture, implementation, releases, and the production support that follows. All three had to hold up on phones and tablets, and on an operations floor rather than at a desk. I worked with the people using them daily, which is the fastest way to find out what a screen actually costs someone mid-shift.', 'CONTRACT', '["konversi-fleet","konversi-pos","konversi-attendance"]', '{"from":"purple","to":"pink"}');
INSERT OR REPLACE INTO experiences (id, name, role, work_start, work_end, location, description, type, works, gradient) VALUES
  ('lovepack', 'Lovepack Consumers Pvt. Ltd.', 'Software Engineer', '2024-08-01', '2026-09-01', 'Remote', 'Sole frontend developer across three product lines — EazyDukan, WebRasoi, and Zluper — owning the mobile and web frontend end-to-end, from architecture through production. All three reached real users: Induskriti, a well-known terracotta chain, ran both its POS and inventory management on EazyDukan, as did several smaller shops. A restaurant or two used WebRasoi''s restaurant-specific flows, and Zluper took orders daily from launch. Took full ownership of the release lifecycle — app store releases, OTA updates, error and performance monitoring, and Core Web Vitals — and contributed to backend and cloud infrastructure when the work called for it, and the final year of it ran alongside a full-time role elsewhere.', 'PART_TIME', '["eazydukan","webrasoi","zluper"]', '{"from":"blue","to":"indigo"}');
INSERT OR REPLACE INTO experiences (id, name, role, work_start, work_end, location, description, type, works, gradient) VALUES
  ('physicswallah', 'PW (PhysicsWallah) Skills', 'Content Writer/Developer', '2023-05-01', '2024-01-01', 'Remote', 'Wrote and built a React Native course that starts at first setup and ends at a release build, taught with Expo throughout. Worked to a brief and a schedule set by a mentor, which turned out to suit me — given the guardrails and a date, the work lands inside them. The curriculum runs from components and navigation up through native modules, performance and store releases, built around worked examples and projects rather than reference prose. Having my own explanations reviewed by someone further along is where a lot of the fundamentals actually set. This came before my first full-time engineering role, which is a strange order — teaching the thing, then going and doing it for a living. It is also why writing something down clearly enough for another developer to follow reads as part of the work to me, not overhead on top of it.', 'FREELANCE', '[]', '{"from":"red","to":"orange"}');
INSERT OR REPLACE INTO experiences (id, name, role, work_start, work_end, location, description, type, works, gradient) VALUES
  ('renovateai', 'Trial & Error Inc.', 'Software Engineer', '2025-09-01', NULL, 'Remote', 'Frontend across iOS, Android and web on a shipping consumer AI product, plus two of the services behind it. Rebuilt onboarding and then A/B tested the new flow against the old one, which is where the conversion gains came from. Set up the app''s design system and removed the two UI libraries it had accumulated, Tamagui and NativeBase, over four phases; a later pass settled the app on a single experience and deleted 268 files and roughly 60,000 lines of what those migrations had left stranded. Built the asset library service every style, material and user upload is served from — curated assets shared, user uploads private, new collections added as data rather than as a schema change — and the remote-config service the app reads its flags and tutorials from, backed by one JSON document the team edits in an internal dashboard. Both were written with AI assistance and neither was architected by it — collections as data rather than schema, and one canonical shape for the config, are the calls that keep them simple. Accessibility went in alongside each feature rather than after it, product analytics with it, and on-call and production triage came with the seat. Frontend problems land on my desk from across the team, including from engineers with more years than I have, and talking them through is a normal part of the week rather than a favour. When the interaction design is mine to work out rather than handed over, what I propose is generally what ships.', 'FULL_TIME', '["renovate-ai","yardplan","video-lab"]', '{"from":"pink","to":"orange"}');

DELETE FROM works WHERE id NOT IN ('eazydukan', 'webrasoi', 'zluper', 'konversi-fleet', 'konversi-pos', 'konversi-attendance', 'bvmrf', 'rhia', 'renovate-ai', 'privycode-mobile', 'yardplan', 'video-lab');
INSERT OR REPLACE INTO works (id, name, description_short, description_long, icon, category, type, app_store_id, play_store_id, is_internal, featured, company_id, technologies, rating, screenshots, web_urls, source_code, google_group_url) VALUES
  ('eazydukan', 'EazyDukan', 'Retail operations platform for small shops and restaurants: a full point of sale with live inventory, multiple outlets and staff, plus AI that builds a shop''s whole catalog from a photograph of its menu. Mobile and web in English, Hindi and Bengali, with a paired tablet as a customer-facing display and a storefront for online orders.', 'EazyDukan is a retail operations platform for small shops and restaurants, sold in subscription tiers, built for both mobile and web, and localized into English, Hindi and Bengali. An owner gets a full point of sale with live inventory, multiple outlets, staff accounts, coupons, returns, and sales and revenue reporting; the web build is the same product with room to breathe, for bulk inventory work and running a till on a larger screen. Payments cover cash, QR and card, plus SMS payment links for a customer who is not standing at the counter. The AI paths are the shortcut that made it worth switching: photograph a printed menu or price list and the app builds the catalog from it, so the owner checks names and prices instead of typing hundreds of rows, and item photography can be generated the same way. Anything that sells out is marked unavailable for the day in one tap. Marketing works like that too — the app drafts a seasonal or discount message and hands it to WhatsApp, addressed to whoever is in the shop. A paired tablet becomes a customer-facing display, with the phone as sender and the tablet as receiver, sitting in the store cycling through what is on offer. Online orders arrive through a storefront that lists nearby shops, where every account gets its own subdomain, so a store can advertise its own address and then fulfil deliveries in-house or hand them to a third party.', 'https://images.sumit.codes/portfolio/works/eazydukan/icon.png', 'Productivity', 'MULTI_PLATFORM', NULL, 'com.eazydukan', 0, 0, 'lovepack', '["React Native","React.js","Next.js","TypeScript","Redux","Zustand","WebSocket","Firebase","Razorpay","Thermal Printers","Bluetooth","Axios","GitLab","Tailwind"]', 0, '["https://images.sumit.codes/portfolio/works/eazydukan/mobile/01-home.jpg","https://images.sumit.codes/portfolio/works/eazydukan/mobile/02-pos-billing.jpg","https://images.sumit.codes/portfolio/works/eazydukan/mobile/03-transaction-logs.jpg","https://images.sumit.codes/portfolio/works/eazydukan/mobile/04-add-product.jpg","https://images.sumit.codes/portfolio/works/eazydukan/mobile/05-product-photo.jpg","https://images.sumit.codes/portfolio/works/eazydukan/mobile/06-menu-setup.jpg","https://images.sumit.codes/portfolio/works/eazydukan/mobile/07-menu-scan.jpg","https://images.sumit.codes/portfolio/works/eazydukan/mobile/08-delivery-radius.jpg","https://images.sumit.codes/portfolio/works/eazydukan/mobile/09-upi-qr.jpg","https://images.sumit.codes/portfolio/works/eazydukan/mobile/10-marketplaces.jpg","https://images.sumit.codes/portfolio/works/eazydukan/web/01-storefront.jpg","https://images.sumit.codes/portfolio/works/eazydukan/web/02-product.jpg","https://images.sumit.codes/portfolio/works/eazydukan/web/03-location.jpg","https://images.sumit.codes/portfolio/works/eazydukan/web/04-catalog.jpg","https://images.sumit.codes/portfolio/works/eazydukan/web/05-cart.jpg","https://images.sumit.codes/portfolio/works/eazydukan/web/06-coupons.jpg","https://images.sumit.codes/portfolio/works/eazydukan/web/07-order-status.jpg","https://images.sumit.codes/portfolio/works/eazydukan/web/08-order-history.jpg","https://images.sumit.codes/portfolio/works/eazydukan/web/09-order-details.jpg"]', '["https://www.eazydukan.com","https://shop.eazydukan.com/"]', NULL, NULL);
INSERT OR REPLACE INTO works (id, name, description_short, description_long, icon, category, type, app_store_id, play_store_id, is_internal, featured, company_id, technologies, rating, screenshots, web_urls, source_code, google_group_url) VALUES
  ('webrasoi', 'WebRasoi', 'The restaurant build of EazyDukan. Photograph a printed menu and the app fills in dishes, prices, descriptions and generated imagery for the owner to review; a dish that runs out comes off the menu for the day in one tap.', 'WebRasoi is EazyDukan rebuilt around a kitchen rather than a shop floor. The catalog becomes a menu, which makes the AI intake path the centre of the product rather than a convenience: photograph the printed menu and the app fills in dishes, prices and descriptions, generating item imagery for kitchens that have never photographed their own food, leaving the owner to review instead of type. A dish that runs out is taken off the menu for the rest of the day in a single tap. Everything a restaurant still needs from the retail product — orders, payments, staff, outlets, reporting, the same English, Hindi and Bengali localization — carries across unchanged; what differs is that every flow assumes service rather than shelves.', '', 'Food & Drink', 'MOBILE', NULL, 'com.webrasoi', 0, 0, 'lovepack', '["React Native","TypeScript","Redux","Zustand","WebSocket","Firebase","Razorpay","Thermal Printers","Bluetooth","Axios","GitLab"]', 0, '["https://images.sumit.codes/portfolio/works/webrasoi/01-manage-menu.jpg","https://images.sumit.codes/portfolio/works/webrasoi/02-inventory-operations.jpg","https://images.sumit.codes/portfolio/works/webrasoi/03-category-details.jpg","https://images.sumit.codes/portfolio/works/webrasoi/04-outlet-management.jpg","https://images.sumit.codes/portfolio/works/webrasoi/05-online-store.jpg","https://images.sumit.codes/portfolio/works/webrasoi/06-orders.jpg","https://images.sumit.codes/portfolio/works/webrasoi/07-order-details.jpg","https://images.sumit.codes/portfolio/works/webrasoi/08-delivery-settings.jpg","https://images.sumit.codes/portfolio/works/webrasoi/09-coupons.jpg","https://images.sumit.codes/portfolio/works/webrasoi/10-configure-checkout.jpg","https://images.sumit.codes/portfolio/works/webrasoi/11-store-marketing.jpg","https://images.sumit.codes/portfolio/works/webrasoi/12-staff-management.jpg","https://images.sumit.codes/portfolio/works/webrasoi/13-card-payments.jpg","https://images.sumit.codes/portfolio/works/webrasoi/14-analytics.jpg","https://images.sumit.codes/portfolio/works/webrasoi/15-wallet-subscription.jpg","https://images.sumit.codes/portfolio/works/webrasoi/16-delivery-partners.jpg","https://images.sumit.codes/portfolio/works/webrasoi/17-storefront-promo.jpg","https://images.sumit.codes/portfolio/works/webrasoi/18-more.jpg"]', '["webrasoi.com"]', NULL, NULL);
INSERT OR REPLACE INTO works (id, name, description_short, description_long, icon, category, type, app_store_id, play_store_id, is_internal, featured, company_id, technologies, rating, screenshots, web_urls, source_code, google_group_url) VALUES
  ('zluper', 'Zluper', 'Thrift fashion marketplace where most stock is one-of-one, so the app is built around discovery instead of search. A full-screen vertical feed ranks on gender and the shopper''s sizes, and a "buy for someone" mode re-ranks it to a friend''s. Built the consumer app for iOS and Android, the web build, the warehouse operations app, and the admin console.', 'Zluper is a thrift fashion marketplace: the stock is mostly one-of-one — a single piece in a single size — plus lowerwear and accessories like rings and keychains. That inventory shape is why the app leads with discovery rather than search. The home experience is a full-screen vertical media feed ranked by gender and by the sizes captured at onboarding, and it auto-selects the shopper''s size when a piece has it, falling back to a size picker when it does not. A "buy for someone" mode swaps in a friend''s sizes and re-ranks the feed to them. Around that sit wishlists, coupons, a wallet with cashback, referrals, a creator program with tiers and payouts, and ticketed in-app support. A shake game gives stock away: shake hard enough for long enough and you win, with the score verified before a prize is drawn and claimed inside a time window. Video streams adaptively, and the feed recycles its rows with a player only for the item on screen, which keeps an endless scroll smooth on cheap Android hardware. The warehouse has its own operations app for barcode scanning, label printing, crate audits and SKU intake, while listings are drafted in an admin console with AI-generated imagery and held for human review before going live. The returns pipeline was built server-side. Shipped across seventeen releases with over-the-air updates, feature flags and a generated analytics catalog.', 'https://images.sumit.codes/portfolio/works/zluper/icon.png', 'Shopping', 'MULTI_PLATFORM', '6754866276', 'com.zluper', 0, 1, 'lovepack', '["Expo","React Native","React.js","Vite","Tailwind","NativeWind","React Query","Zustand","AWS","Google Cloud Console","EAS","Redux","Firebase","Sentry","TypeScript","PostHog","Razorpay SDK"]', 0, '["https://images.sumit.codes/portfolio/works/zluper/mobile/01-home.jpg","https://images.sumit.codes/portfolio/works/zluper/mobile/02-product-detail.jpg","https://images.sumit.codes/portfolio/works/zluper/mobile/03-co-ord-sets.jpg","https://images.sumit.codes/portfolio/works/zluper/mobile/04-categories.jpg","https://images.sumit.codes/portfolio/works/zluper/mobile/05-product.jpg","https://images.sumit.codes/portfolio/works/zluper/mobile/06-cart.jpg","https://images.sumit.codes/portfolio/works/zluper/mobile/07-cart-coupon.jpg","https://images.sumit.codes/portfolio/works/zluper/mobile/08-order-history.jpg","https://images.sumit.codes/portfolio/works/zluper/mobile/09-returns.jpg","https://images.sumit.codes/portfolio/works/zluper/mobile/10-profile.jpg","https://images.sumit.codes/portfolio/works/zluper/web/01-home.jpg","https://images.sumit.codes/portfolio/works/zluper/web/02-listing.jpg","https://images.sumit.codes/portfolio/works/zluper/web/03-product.jpg","https://images.sumit.codes/portfolio/works/zluper/web/04-filters.jpg","https://images.sumit.codes/portfolio/works/zluper/web/05-checkout.jpg","https://images.sumit.codes/portfolio/works/zluper/web/06-order-success.jpg","https://images.sumit.codes/portfolio/works/zluper/web/07-profile.jpg"]', '["zluper.com"]', NULL, NULL);
INSERT OR REPLACE INTO works (id, name, description_short, description_long, icon, category, type, app_store_id, play_store_id, is_internal, featured, company_id, technologies, rating, screenshots, web_urls, source_code, google_group_url) VALUES
  ('konversi-fleet', 'Konversi Fleet - Truck Fleet Management App', 'Fleet maintenance app for a trucking operation. Scan a vehicle''s QR code and its job opens with the drop-off point and an estimated arrival time; weekly inspection checklists, a position-by-position tire diagram, parts logging and photo evidence all attach to the job.', 'A fleet maintenance app for a trucking operation, built around the technician rather than the dispatcher. Vehicles carry QR codes: scan one and the job opens with its details, its drop-off point and an estimated time to reach the site, and the technician starts and works it from there. Weekly checklists walk an inspection across the whole vehicle, a tire diagram records condition and replacements position by position, and anything urgent becomes its own job with a table of the parts and quantities it consumed. Photos attach to a job as the record of what was picked up or repaired, and a technician logs the work actually done rather than just closing the ticket. In-progress and completed jobs sit in their own views, every vehicle keeps an inspection history, and roles separate what a technician sees from what an operator does.', '', 'Logistics', 'MOBILE', NULL, NULL, 1, 0, 'konversi', '["Expo","React Native","TypeScript","Axios","Redux","GitHub","CI/CD","SumoLogic"]', 0, '["https://images.sumit.codes/portfolio/works/konversi-fleet/01-weekly-checklist.jpg","https://images.sumit.codes/portfolio/works/konversi-fleet/02-replace-tires.jpg","https://images.sumit.codes/portfolio/works/konversi-fleet/03-vehicle-list.jpg","https://images.sumit.codes/portfolio/works/konversi-fleet/04-tire-diagram.jpg","https://images.sumit.codes/portfolio/works/konversi-fleet/05-urgent-maintenance.jpg","https://images.sumit.codes/portfolio/works/konversi-fleet/06-job-order-dropoff.jpg","https://images.sumit.codes/portfolio/works/konversi-fleet/07-job-order-map.jpg","https://images.sumit.codes/portfolio/works/konversi-fleet/08-inspection-history.jpg"]', NULL, NULL, NULL);
INSERT OR REPLACE INTO works (id, name, description_short, description_long, icon, category, type, app_store_id, play_store_id, is_internal, featured, company_id, technologies, rating, screenshots, web_urls, source_code, google_group_url) VALUES
  ('konversi-pos', 'Konversi POS - Full-fledged POS App', 'Point of sale for park operations at 1,000+ transactions a day, with per-outlet stock across a chain and QR-coded receipts printed from a paired thermal printer — the printing built as a native module, because nothing off the shelf produced it.', 'A point of sale for park operations, running 1,000+ transactions a day. One account covers a whole chain: each site is a selectable outlet and the till only offers stock that outlet actually holds, so an invoice cannot be raised against inventory sitting somewhere else. Order summary, payment method and receipt are one continuous flow, and the app pairs straight to a thermal printer to print a ticket carrying a QR code alongside the full transaction detail. That printing was the hard part — nothing off the shelf produced the QR receipt this needed, so it was built as a native module. Reporting covers transaction history and the end-of-day closing report the site reconciles against.', '', 'Point of Sale', 'MOBILE', NULL, NULL, 1, 0, 'konversi', '["Expo","React Native","TypeScript","Axios","Redux","GitHub","CI/CD","SumoLogic","Bluetooth","Thermal Printers"]', 0, '["https://images.sumit.codes/portfolio/works/konversi-pos/01-home.jpg","https://images.sumit.codes/portfolio/works/konversi-pos/02-order-summary.jpg","https://images.sumit.codes/portfolio/works/konversi-pos/03-payment-method.jpg","https://images.sumit.codes/portfolio/works/konversi-pos/04-print-ticket.jpg","https://images.sumit.codes/portfolio/works/konversi-pos/05-reports.jpg","https://images.sumit.codes/portfolio/works/konversi-pos/06-history.jpg","https://images.sumit.codes/portfolio/works/konversi-pos/07-closing-report.jpg"]', NULL, NULL, NULL);
INSERT OR REPLACE INTO works (id, name, description_short, description_long, icon, category, type, app_store_id, play_store_id, is_internal, featured, company_id, technologies, rating, screenshots, web_urls, source_code, google_group_url) VALUES
  ('konversi-attendance', 'KWork - Attendance Tracking/Logging App', 'Attendance app that makes clocking in verifiable rather than trusted: a photo goes to the backend and the device''s location is checked against a radius the organization sets. Leave requests run through the same app, single date or range, tracked through approval.', 'An attendance app that makes clocking in verifiable rather than trusted. A clock-in sends a photo to the backend and checks the device''s location against a radius the organization sets, so a shift can only be opened from inside the workplace, and daily hours accumulate from the clock-in and clock-out pairs. Leave runs through the same app: pick a single date or a range, raise the request, and follow it through pending, accepted or rejected. It stayed a work in progress, with the verification and leave workflows as the parts that worked end to end.', '', 'Workforce', 'MOBILE', NULL, NULL, 1, 0, 'konversi', '["Expo","React Native","TypeScript","GitHub","CI/CD","Axios","SumoLogic","Redux"]', 0, '["https://images.sumit.codes/portfolio/works/konversi-attendance/01-login.jpg","https://images.sumit.codes/portfolio/works/konversi-attendance/02-clock-in.jpg","https://images.sumit.codes/portfolio/works/konversi-attendance/03-apply-leave.jpg","https://images.sumit.codes/portfolio/works/konversi-attendance/04-leave-range.jpg","https://images.sumit.codes/portfolio/works/konversi-attendance/05-leave-requests.jpg"]', NULL, NULL, NULL);
INSERT OR REPLACE INTO works (id, name, description_short, description_long, icon, category, type, app_store_id, play_store_id, is_internal, featured, company_id, technologies, rating, screenshots, web_urls, source_code, google_group_url) VALUES
  ('bvmrf', 'BVMRF - Vet Health', 'A white-label health app: one codebase, a separately branded release for each client. The build shown here is the public one, serving Veterans with educational material, a facilities directory and benefits guidance. Underneath sat a JavaScript codebase with no TypeScript, which is where most of the work went.', 'One codebase, several clients: this was a white-label health app where each client got its own branded release off a shared template. The build shown here is the public one, for a foundation supporting Veterans, and it is the version that demonstrates the features — the two iterations worked on directly were a clinical-trial companion for a US medical client, which never shipped, and a build for a large US retailer. What the released app does: a library of educational material tailored to a user''s therapeutic areas, a directory of Veterans Affairs facilities and services, guidance on eligibility and benefits, and news on research and clinical trials a user might be eligible to join. The interesting part was underneath. It was a JavaScript codebase with no TypeScript, so the work was performance passes, pulling out legacy code, repairing styling that had drifted, and adding features to a template that several clients depended on.', 'https://images.sumit.codes/portfolio/works/bvmrf/icon.png', 'Education', 'MOBILE', '6476032857', 'my.bvmrf.app', 0, 1, 'ariveguru', '["React Native","Bitbucket","JavaScript","Redux","Redux Saga"]', 0, '["https://images.sumit.codes/portfolio/works/bvmrf/01-splash.jpg","https://images.sumit.codes/portfolio/works/bvmrf/02-login.jpg","https://images.sumit.codes/portfolio/works/bvmrf/03-home.jpg","https://images.sumit.codes/portfolio/works/bvmrf/04-quick-menu.jpg","https://images.sumit.codes/portfolio/works/bvmrf/05-badges.jpg","https://images.sumit.codes/portfolio/works/bvmrf/06-badge-detail.jpg","https://images.sumit.codes/portfolio/works/bvmrf/07-surveys.jpg","https://images.sumit.codes/portfolio/works/bvmrf/08-trials.jpg","https://images.sumit.codes/portfolio/works/bvmrf/09-resources.jpg","https://images.sumit.codes/portfolio/works/bvmrf/10-articles.jpg"]', NULL, NULL, NULL);
INSERT OR REPLACE INTO works (id, name, description_short, description_long, icon, category, type, app_store_id, play_store_id, is_internal, featured, company_id, technologies, rating, screenshots, web_urls, source_code, google_group_url) VALUES
  ('rhia', 'RHIA - Life-like AI Assistant', 'A voice-first stand-in for the receptionist desk: walk up, ask about the company it was set up for, book an appointment. Registration ran entirely by voice, down to reading a one-time code back to it. A proof of concept, built before grounding an assistant in a company''s own data was routine.', 'RHIA was an attempt at the receptionist desk you walk past in every office building: something you approach, talk to, and get answers from. It was set up per company, so it could answer questions about that specific organization from the material it had been given, and it could book appointments. Registration happened entirely by voice — speak your phone number, receive a one-time code, and read the code back to confirm it, with no keyboard anywhere in the flow. Built as a proof of concept, and it was ambitious for its moment: this predated the tooling that now makes grounding an assistant in a company''s own data routine, so most of it had to be assembled rather than wired together, and it was heading for a demo at the Bengaluru Tech Summit.', '', 'Conversational AI', 'WEB', NULL, NULL, 0, 0, 'ariveguru', '["React","Vite","Tailwind","HeyGen","AI/ML","OpenAI","Gemini","Zustand","Axios","JavaScript","Bitbucket","WebSocket"]', 0, '[]', NULL, NULL, NULL);
INSERT OR REPLACE INTO works (id, name, description_short, description_long, icon, category, type, app_store_id, play_store_id, is_internal, featured, company_id, technologies, rating, screenshots, web_urls, source_code, google_group_url) VALUES
  ('renovate-ai', 'Renovate AI', 'AI home design app: photograph a room, facade or yard and get it redesigned — virtual staging, paint previews, object removal, sketch-to-render, 4K upscaling — across more than a hundred curated styles. A canvas and material matching give direct control rather than prompt-guessing, and a design consultation flow hands a project to a human designer.', 'Renovate AI turns a photograph of a room, a facade or a yard into a finished redesign, then keeps going from there. Virtual staging fills an empty room, interior and exterior paint previews put a color on the actual wall, furniture gets rearranged, objects get removed, sketches become renders, and an image can be upscaled to 4K — more than ten models behind over a hundred curated interior and exterior styles. A canvas hands the user direct control over what changes instead of leaving it to a prompt, material match lifts a specific finish out of a catalog and applies it in place, and an inspiration library keeps the references that got them there. Renders branch into their own iterations, so a variation can be chased without losing the version worth keeping, and the history stays browsable. For anyone who would rather have a person than a model, a design consultation flow hands the project to a human designer, with the brief and assets collected in the app. It runs on iOS, Android and a web studio, with in-app tutorials, subscription tiers and push notifications around the core product.', 'https://images.sumit.codes/portfolio/works/renovate-ai/icon.png', 'Graphics & Design', 'MULTI_PLATFORM', '1661709494', 'app.renovateai', 0, 1, 'renovateai', '["React Native","TypeScript","Redux","Axios","React Query","Redux Saga","GitHub","CI/CD","Expo","Expo UI","Firebase","RevenueCat","Sentry","PostHog"]', 4.64, '["https://images.sumit.codes/portfolio/works/renovate-ai/01-remodel-with-ai.jpg","https://images.sumit.codes/portfolio/works/renovate-ai/02-any-style.jpg","https://images.sumit.codes/portfolio/works/renovate-ai/03-kitchen-and-bath.jpg","https://images.sumit.codes/portfolio/works/renovate-ai/04-type-what-you-want.jpg","https://images.sumit.codes/portfolio/works/renovate-ai/05-floors-counters.jpg","https://images.sumit.codes/portfolio/works/renovate-ai/06-wall-colors-live.jpg","https://images.sumit.codes/portfolio/works/renovate-ai/07-paint-instantly.jpg","https://images.sumit.codes/portfolio/works/renovate-ai/08-materials.jpg","https://images.sumit.codes/portfolio/works/renovate-ai/09-living-room-render.jpg","https://images.sumit.codes/portfolio/works/renovate-ai/10-cost-estimate.jpg"]', '["https://studio.renovateai.app"]', NULL, NULL);
INSERT OR REPLACE INTO works (id, name, description_short, description_long, icon, category, type, app_store_id, play_store_id, is_internal, featured, company_id, technologies, rating, screenshots, web_urls, source_code, google_group_url) VALUES
  ('privycode-mobile', 'PrivyCode - Safe Code Sharing', 'Personal project: the mobile companion to the open-source PrivyCode web app, on the same backend. Sign in with GitHub, browse your repositories, and hand someone a view-only link to a private one that expires — built to learn OAuth, token handling on a device, and access that is genuinely time-limited.', 'A personal project, and a small one on purpose. PrivyCode gives a private GitHub repository a view-only link that expires, so code can be shown to a recruiter or a client without making the repository public or handing over collaborator access. This is the mobile companion to the open-source web version, running against the same backend: sign in with GitHub, browse your repositories, and generate a link that lets the recipient read but not clone, download or modify. It was built to work through the parts that are easy to get wrong rather than to ship a product — the GitHub OAuth handshake, holding a token on a device, and enforcing access that is genuinely one-time and time-limited rather than merely hidden.', 'https://images.sumit.codes/portfolio/works/privycode-mobile/icon.png', 'Productivity', 'MOBILE', NULL, 'com.samtastic.privycodemobile', 0, 1, NULL, '["Expo","React Native","Reanimated","GitHub","EAS","Firebase"]', 0, '["https://images.sumit.codes/portfolio/works/privycode-mobile/01-welcome.jpg","https://images.sumit.codes/portfolio/works/privycode-mobile/02-generate-link.jpg","https://images.sumit.codes/portfolio/works/privycode-mobile/03-analytics.jpg"]', '["https://privycode.com"]', NULL, NULL);
INSERT OR REPLACE INTO works (id, name, description_short, description_long, icon, category, type, app_store_id, play_store_id, is_internal, featured, company_id, technologies, rating, screenshots, web_urls, source_code, google_group_url) VALUES
  ('yardplan', 'YardPlan', 'AI landscaping app: photograph a yard, explore renders that branch off one another, then get a buildable plan with plants suited to the region. A two-person build, and the effort went into making a cross-platform app feel genuinely native on iOS — real platform controls, haptics, and render progress that keeps ticking on the Lock Screen while the app is closed.', 'YardPlan turns a photograph of a yard into a redesign, and then into something buildable: renders to explore, and a plan with plants that suit the region. Built fresh by two engineers, with most of the mobile app and about half the backend written here. Renders form a tree rather than a chain — one starts either from the original photo or from another render''s output, so trying a different direction is just another branch, and the request carries no image because the server resolves the input from the parent. Generation runs on its own queue, so a render outlives the app being closed and is only called failed once retries are exhausted. Nothing double-charges for that: one job at a time, a deterministic key so a redelivered job resumes from the image it already made, and a refund in exactly one place. Frontend is the specialism, and the backend was written with AI assistance — but the decisions were not delegated along with the typing: what the queue had to guarantee, where state was allowed to live, what a failed job must never cost. Most of the effort, though, went into making a cross-platform app feel like a native iOS one. Sheets, context menus and the segmented control are real platform controls rather than imitations, glass steps down to system blur on older iOS and on Android, every tappable surface answers with haptics, and pinch-to-zoom settles on a spring. Render progress shows up on the Lock Screen and Dynamic Island, animated by the system from a pair of timestamps, so it keeps moving with the app suspended or killed. Both sides hold themselves to written rules — one-way dependencies between layers, semantic color tokens, generated event names so no analytics string is typed by hand — and the backend''s 597 tests run against the real migrations on a real database rather than mocks, because the SQL is what is under test; it ships on both stores, in English and Spanish.', 'https://images.sumit.codes/portfolio/works/yardplan/icon.png', 'Graphics & Design', 'MOBILE', '6784333021', 'app.yardplan', 0, 1, 'renovateai', '["Expo","React Native","React 19","React Compiler","TypeScript","expo-router","uniwind","Tailwind","React Query","Redux Toolkit","Firebase","RevenueCat","PostHog","Branch","Lingui","Reanimated","Skia","MMKV","EAS","Cloudflare Workers","Hono","D1","R2","Cloudflare Queues","Drizzle","Gemini","Biome","Jest"]', 4.65, '["https://images.sumit.codes/portfolio/works/yardplan/01-reimagine-your-yard.jpg","https://images.sumit.codes/portfolio/works/yardplan/02-priced-plan.jpg","https://images.sumit.codes/portfolio/works/yardplan/03-describe-your-dream.jpg","https://images.sumit.codes/portfolio/works/yardplan/04-know-what-grows.jpg","https://images.sumit.codes/portfolio/works/yardplan/05-redesigned-yard.jpg","https://images.sumit.codes/portfolio/works/yardplan/06-build-this-weekend.jpg"]', NULL, NULL, NULL);
INSERT OR REPLACE INTO works (id, name, description_short, description_long, icon, category, type, app_store_id, play_store_id, is_internal, featured, company_id, technologies, rating, screenshots, web_urls, source_code, google_group_url) VALUES
  ('video-lab', 'Video Lab', 'An AI video generator built around a catalog instead of a prompt box: pick a template, hand it a photo, and it renders — or write your own prompt and choose the model and style. Subscription-gated, with coins that generations spend. Built solo, app and backend.', 'Video Lab turns a photo into a short AI video. The home screen is a catalog rather than a prompt box — a hero carousel and category sections like flying or viral effects, each template a looping preview with a one-line pitch — so you pick a look, hand it a photo, and it renders. There is a free-form path too: write a prompt and choose the model and the style yourself. The app is subscription-gated end to end, a subscription grants the coins that generations spend, and a template shows its cost before you commit to it. Built solo, app and backend, and the decisions underneath are the part worth reading. A template is always image-to-video, so nothing stores what kind of thing a template is: the request shape decides the pipeline, and the two request bodies are a union of closed objects rather than one object with optional fields, so the rules fall out of the shapes instead of being checked after the fact. Models are rows, not an enum — a new one launches as an insert, disabling one drops it from the picker and stops it being accepted in the same instant, and it stays readable because old jobs still point at it. Every vendor sits behind one adapter, submit a job and poll a handle, so the pipeline never learns a vendor''s name and adding one is three edits and no change to the pipeline. Generation runs on a durable workflow that outlives the request, catalog assets are public while anything a user made stays private, and credits are ours to account for while subscription state is mirrored in from the store.', 'https://images.sumit.codes/portfolio/works/video-lab/icon.png', 'Photo & Video', 'MOBILE', NULL, NULL, 0, 1, 'renovateai', '["Expo","React Native","TypeScript","Reanimated","Skia","Redux Toolkit","React Query","Firebase Auth","RevenueCat","Cloudflare Workers","Hono","D1","R2","Drizzle"]', 0, '["https://images.sumit.codes/portfolio/works/video-lab/01-start-with-a-look.jpg","https://images.sumit.codes/portfolio/works/video-lab/02-bring-one-photo.jpg","https://images.sumit.codes/portfolio/works/video-lab/03-tap-continue.jpg","https://images.sumit.codes/portfolio/works/video-lab/04-get-a-video-back.jpg","https://images.sumit.codes/portfolio/works/video-lab/05-keep-it-or-send-it.jpg","https://images.sumit.codes/portfolio/works/video-lab/06-trim-it-first.jpg"]', '["https://video.voxapp.ai"]', NULL, NULL);

